INSERT INTO announcements (id, title, content, posted_by, target_role) VALUES ('ann-01', 'Bethelhem Youth Academy Academic Council Resolution', 'All physical classes will compile evaluations on June 15th for the Quarter 4 consolidation check. Double session parent gates open at 3:30 PM.', 'u-admin-01', 'all');
INSERT INTO announcements (id, title, content, posted_by, target_role) VALUES ('ann-02', 'Quarterly Teacher In-Service Briefing', 'Standard portal training for uploading student attendance modules and tracking double afternoon roll logs is scheduled for next Saturday.', 'u-admin-01', 'teachers');
INSERT INTO announcements (id, title, content, posted_by, target_role) VALUES ('ann-03', 'Security Gate Log Consolidation', 'To support safety checks, students must wear their standardized barcode badges at arrival (morning session check-in) and departure.', 'u-admin-01', 'parents');
INSERT INTO announcements (id, title, content, posted_by, target_role) VALUES ('ann-04', 'Grade 8 National Assessment Preparations', 'Junior High student cohorts will hold mandatory mock subject exams in Mathematics, General Science, and English on Tuesdays.', 'u-admin-01', 'students');
INSERT INTO announcements (id, title, content, posted_by, target_role) VALUES ('ann-05', 'Annual Sports Day Registration [Draft]', 'Draft syllabus plan explaining track races, community football matches, and student award lists across sections.', 'u-admin-01', 'all');
